# Owner(s): ["module: inductor"]
# [MODULE DOC] Tests that the Python wrapper module generated by inductor for GPU code can be
# run as a standalone script in a subprocess and exposes helper functions for building benchmark
# arguments. Tests clear the code cache first and run only when a GPU is available.

import inspect
import os
import re
import subprocess
import sys

import torch
import torch._inductor.async_compile
from torch._inductor.codecache import PyCodeCache
from torch._inductor.test_case import run_tests, TestCase
from torch.testing._internal.inductor_utils import GPU_TYPE, HAS_GPU


class TestTritonWrapper(TestCase):
    # [CLASS DOC] Tests of the generated inductor wrapper module: standalone execution, argument
    # builder and alias preservation. Each test compiles a small function and inspects the
    # single cached wrapper module.
    def setUp(self):
        # [FUNCTION DOC] Calls the base setUp then clears the Python code cache so each test
        # sees only its own compiled module.
        super().setUp()
        PyCodeCache.cache_clear()

    def get_compiled_module(self):
        # [FUNCTION DOC] HELPER: Scans the cached modules for those defining the benchmark entry
        # point, asserts there is exactly one and returns it. Fails the test if none or several
        # are found.
        compiled_module = None
        for v in PyCodeCache.modules:
            if hasattr(v, "benchmark_compiled_module"):
                self.assertTrue(
                    compiled_module is None, "Found multiple compiled modules"
                )
                compiled_module = v

        self.assertTrue(compiled_module is not None)
        return compiled_module

    def test_wrapper_using_gpu_seed(self):
        # [FUNCTION DOC] Compiles a function applying dropout and adding an input on the
        # GPU, runs it once, then launches the generated wrapper file in a subprocess using
        # the same interpreter, with the parent module search path added to the child
        # environment. Asserts the process exits successfully (a failure raises an error)
        # and printed some output.
        """
        Make sure the subprocess.check_output does not throw.
        """

        @torch.compile
        def f(x, y):
            # [FUNCTION DOC] HELPER: Compiled function: applies dropout with probability one
            # half to the first input and adds the second input.
            # dropout will result in usage of cuda_seed
            z = torch.nn.functional.dropout(x, 0.5)
            return z + y

        N = 10
        x = torch.rand(N).to(device=GPU_TYPE)
        y = torch.rand(N).to(device=GPU_TYPE)
        out = f(x, y)  # noqa: F841
        compiled_module = self.get_compiled_module()
        # to make sure the subprocess runs on the exact same path as the parent process
        # we augment the PYTHONPATH env var
        augmented_pp = ":".join(sys.path)
        if os.environ.get("PYTHONPATH"):
            augmented_pp = f"{os.environ.get('PYTHONPATH')}:{augmented_pp}"
        # now run the compiled module in subprocess and check its output
        bench_out = subprocess.check_output(
            f"{sys.executable} {compiled_module.__file__}".split(),
            stderr=subprocess.STDOUT,
            env={**os.environ, "PYTHONPATH": augmented_pp},
        ).decode()

        self.assertTrue(len(bench_out) > 0)

    def test_get_args_and_benchmark_compiled_module(self):
        @torch.compile
        # [FUNCTION DOC] Compiles an elementwise multiply-add on the GPU and checks the
        # generated module has a callable argument builder and a benchmark function taking an
        # args parameter. Calls the builder and asserts it returns a non-empty list, then runs
        # the module file in a subprocess with the augmented search path and asserts it succeeds
        # with non-empty output.
        def f(x, y):
            return x * y + x
            # [FUNCTION DOC] HELPER: Compiled function returning the first input times the
            # second plus the first.

        N = 10
        x = torch.rand(N).to(device=GPU_TYPE)
        y = torch.rand(N).to(device=GPU_TYPE)
        f(x, y)

        compiled_module = self.get_compiled_module()

        # Verify get_args function exists and is callable
        self.assertTrue(hasattr(compiled_module, "get_args"))
        self.assertTrue(callable(compiled_module.get_args))

        self.assertTrue(hasattr(compiled_module, "benchmark_compiled_module"))
        sig = inspect.signature(compiled_module.benchmark_compiled_module)
        self.assertIn("args", sig.parameters)

        args = compiled_module.get_args()
        self.assertIsInstance(args, list)
        self.assertTrue(len(args) > 0)

        # Verify that running the compiled module as a subprocess works
        augmented_pp = ":".join(sys.path)
        if os.environ.get("PYTHONPATH"):
            augmented_pp = f"{os.environ.get('PYTHONPATH')}:{augmented_pp}"
        bench_out = subprocess.check_output(
            f"{sys.executable} {compiled_module.__file__}".split(),
            stderr=subprocess.STDOUT,
            env={**os.environ, "PYTHONPATH": augmented_pp},
        ).decode()
        self.assertTrue(len(bench_out) > 0)

    def test_get_args_preserves_aliased_inputs(self):
        @torch.compile
        # [FUNCTION DOC] Compiles a function over two overlapping strided views of one base
        # tensor plus two empty tensors, then inspects the source of the generated argument
        # builder. Asserts exactly one shared storage variable is created and exactly two
        # strided views are made from it, then runs the builder and asserts the first two
        # returned tensors share the same storage address and four arguments are returned.
        def f(x, y, empty_bool, empty_long):
            return x + y, empty_bool.logical_not(), empty_long + 1
            # [FUNCTION DOC] HELPER: Compiled function returning the sum of the first two
            # inputs, the logical negation of the empty boolean input and the empty long input
            # plus one.

        base = torch.arange(64, device=GPU_TYPE, dtype=torch.long)
        x = torch.as_strided(base, (3, 4), (4, 1), 2)
        y = torch.as_strided(base, (3, 4), (4, 1), 10)
        empty_bool = torch.empty((0, 3), device=GPU_TYPE, dtype=torch.bool)
        empty_long = torch.empty((0, 2), device=GPU_TYPE, dtype=torch.long)
        f(x, y, empty_bool, empty_long)

        compiled_module = self.get_compiled_module()
        get_args_src = inspect.getsource(compiled_module.get_args)
        shared_storage_names = re.findall(
            r"(_shared_storage_\d+) = rand_strided\(",
            get_args_src,
        )
        self.assertEqual(len(shared_storage_names), 1, get_args_src)

        shared_storage = shared_storage_names[0]
        aliased_view_lines = re.findall(
            rf"^\s+\w+ = torch\.as_strided\({shared_storage}, .*$",
            get_args_src,
            re.MULTILINE,
        )
        self.assertEqual(len(aliased_view_lines), 2, get_args_src)

        args = compiled_module.get_args()
        recreated_x, recreated_y, _, _ = args

        self.assertEqual(
            recreated_x.untyped_storage().data_ptr(),
            recreated_y.untyped_storage().data_ptr(),
        )
        self.assertEqual(len(args), 4)


if __name__ == "__main__":
    if HAS_GPU:
        run_tests()
